PowerShell: $f='tests\inventario.test.mjs'; $t=Get-Content $f -Raw -Encoding utf8; $t=$t -replace '"LPZ"','"LPZ01"' -replace '"SCZ"','"SCZ01"'; $t += @'

test("Código de almacén: debe cumplir el estándar de empresa (ciudad en 3 letras + 2 dígitos)", () => {
  for (const almacen of ["LPZ01", "SCZ12", "CIJ99"]) {
    assert.equal(registrarMovimiento([], { tipo: "ingreso", articulo: "A1", almacen, cantidad: 1 }).length, 1);
  }
  for (const almacen of ["LPZ", "lpz01", "LPZ-01", "LPZ1", "LPZ001", "XXX01", "Central La Paz", " LPZ01"]) {
    assert.throws(
      () => registrarMovimiento([], { tipo: "ingreso", articulo: "A1", almacen, cantidad: 1 }),
      /Código de almacén inválido/,
      almacen,
    );
  }
});
'@; Set-Content $f $t -Encoding utf8; npm test 2>&1 | Select-String -Pattern "^# (pass|fail)"

